import React from "react";
import axiosInstance from "../configurations/instance";

class ForgetPassword extends React.Component {
  constructor(props) {
    super(props);
    this.state = {
      step: 1,
      email: "",
      code: "",
      newPassword: "",
      message: "",
      error: "",
    };
  }

  handleInputChange = (event) => {
    const { name, value } = event.target;
    this.setState({ [name]: value });
  };

  handleSendResetCode = () => {
    const { email } = this.state;
    axiosInstance
      .post("/auth/send-reset-code", { email })
      .then((response) => {
        this.setState({ message: response.data.message, error: "", step: 2 });
      })
      .catch((err) => {
        this.setState({ error: err.response?.data?.message || "Произошла ошибка", message: "" });
      });
  };

  handleVerifyResetCode = () => {
    const { email, code } = this.state;
    axiosInstance
      .post("/auth/verify-reset-code", { email, code })
      .then((response) => {
        this.setState({ message: response.data.message, error: "", step: 3 });
      })
      .catch((err) => {
        this.setState({ error: err.response?.data?.message || "Произошла ошибка", message: "" });
      });
  };

  handleResetPassword = () => {
    const { email, newPassword } = this.state;
    axiosInstance
      .post("/auth/reset-password", { email, newPassword })
      .then((response) => {
        this.setState({ message: response.data.message, error: "", step: 4 });
      })
      .catch((err) => {
        this.setState({ error: err.response?.data?.message || "Произошла ошибка", message: "" });
      });
  };

  render() {
    const { step, email, code, newPassword, message, error } = this.state;

    return (
      <div className="forget-password-container">
        <h1>Сброс пароля</h1>

        {step === 1 && (
          <div className="step">
            <h3>Введите ваш email</h3>
            <input
              type="email"
              name="email"
              placeholder="Введите ваш email"
              value={email}
              onChange={this.handleInputChange}
            />
            <button onClick={this.handleSendResetCode}>Отправить код</button>
          </div>
        )}

        {step === 2 && (
          <div className="step">
            <h3>Введите код из email</h3>
            <input
              type="text"
              name="code"
              placeholder="Введите код"
              value={code}
              onChange={this.handleInputChange}
            />
            <button onClick={this.handleVerifyResetCode}>Подтвердить код</button>
          </div>
        )}

        {step === 3 && (
          <div className="step">
            <h3>Введите новый пароль</h3>
            <input
              type="password"
              name="newPassword"
              placeholder="Введите новый пароль"
              value={newPassword}
              onChange={this.handleInputChange}
            />
            <button onClick={this.handleResetPassword}>Сбросить пароль</button>
          </div>
        )}

        {step === 4 && (
          <div className="step">
            <h3>Ваш пароль успешно сброшен!</h3>
            <p>Теперь вы можете войти в систему с новым паролем.</p>
          </div>
        )}

        {message && <p className="success-message">{message}</p>}
        {error && <p className="error-message">{error}</p>}
      </div>
    );
  }
}

export default ForgetPassword;
